const input=$json.body??$json;
const arr=v=>Array.isArray(v)?v:[];
const truthy=v=>v===true||v==="true"||v===1||v==="1";
const blockers=arr(input.blockers);
const requiredDocs=arr(input.required_documents);
const suppliedDocs=arr(input.supplied_documents);
const requiredMilestones=arr(input.required_milestones);
const completedMilestones=arr(input.completed_milestones);
const parties=arr(input.parties);
const packageState=input.closing_package??{};
const auth=input.authorization??{};
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const packageFinalized=truthy(packageState.finalized)||["finalized","ready","complete"].includes(String(packageState.status||"").toLowerCase());
const docsComplete=requiredDocs.length===0||requiredDocs.every(r=>suppliedDocs.some(s=>String(s.id??s)===String(r.id??r)));
const milestonesComplete=requiredMilestones.length===0||requiredMilestones.every(r=>arr(completedMilestones).some(s=>String(s.id??s)===String(r.id??r)));
const partiesComplete=parties.length>=2||Boolean(input.seller&&(input.buyer||input.assignee));
const executedAgreement=truthy(input.executed_agreement)||["executed","signed","fully_executed"].includes(String(input.agreement_status||"").toLowerCase());
const closingDateValid=Boolean(input.closing_date)&&!Number.isNaN(new Date(input.closing_date).getTime());
const closingDateFuture=closingDateValid&&new Date(input.closing_date)>=new Date();
const price=Number(input.contract_price??input.agreed_price??input.purchase_price);
const mao=Number(input.dynamic_mao??input.mao);
const maoProtected=!Number.isFinite(price)||!Number.isFinite(mao)||price<=mao;
const blockersClear=blockers.length===0;
const authorizationConfirmed=truthy(auth.confirmed)||["confirmed","authorized","approved"].includes(String(auth.status||"").toLowerCase());
const authorizationType=String(auth.type||auth.authorization_type||"").trim();
const launchKey=String(input.launch_idempotency_key||input.execution_idempotency_key||"").trim();
const ready=identityComplete&&packageFinalized&&docsComplete&&milestonesComplete&&partiesComplete&&executedAgreement&&closingDateValid&&closingDateFuture&&maoProtected&&blockersClear&&authorizationConfirmed&&authorizationType&&launchKey;

let status="authorization_required",nextWorkflow="WF-277",humanReview=true;
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";}
else if(!packageFinalized){status="package_not_finalized";nextWorkflow="WF-276";}
else if(!docsComplete||!milestonesComplete||!partiesComplete||!executedAgreement){status="final_readiness_evidence_incomplete";nextWorkflow="WF-276";}
else if(!closingDateValid||!closingDateFuture||!blockersClear||!maoProtected){status="blocked";nextWorkflow="WF-126";}
else if(!authorizationConfirmed||!authorizationType||!launchKey){status="authorization_required";nextWorkflow="WF-277";}
else {status="final_closing_ready";nextWorkflow="WF-278";}

return [{json:{...input,workflow:"WF-277",workflow_name:"Closing Package Finalization → Final Closing Readiness & Authorization Controller",status,final_readiness:{identity_complete:identityComplete,package_finalized:packageFinalized,documents_complete:docsComplete,milestones_complete:milestonesComplete,parties_complete:partiesComplete,executed_agreement:executedAgreement,closing_date_valid:closingDateValid,closing_date_future:closingDateFuture,mao_protected:maoProtected,blockers_clear:blockersClear,authorization_confirmed:authorizationConfirmed,authorization_type_present:Boolean(authorizationType),launch_idempotency_key_present:Boolean(launchKey),ready},next_workflow:nextWorkflow,human_review_required:humanReview,routing_reason:status,audit:{event_type:"final_closing_readiness_authorization",idempotency_key:input.idempotency_key||`wf-277:${input.deal_id||"unknown"}:${launchKey||"none"}:${input.version||1}`}}}];
